CREATE TABLE "WW_CATEGORIES"
(
    "ID"          NUMBER(10) GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
    "PARENT_ID"   NUMBER(10)     DEFAULT 0                    NOT NULL,
    "LFT"         NUMBER(10)     DEFAULT 0                    NOT NULL,
    "RGT"         NUMBER(10)     DEFAULT 0                    NOT NULL,
    "LEVEL"       NUMBER(10)     DEFAULT 0                    NOT NULL,
    "PATH"        VARCHAR2(1024) DEFAULT ' '                  NOT NULL,
    "TYPE"        VARCHAR2(50)   DEFAULT ' '                  NOT NULL,
    "TITLE"       VARCHAR2(255)  DEFAULT ' '                  NOT NULL,
    "ALIAS"       VARCHAR2(255)  DEFAULT ' '                  NOT NULL,
    "IMAGE"       VARCHAR2(255)  DEFAULT ' '                  NOT NULL,
    "DESCRIPTION" CLOB,
    "STATE"       NUMBER(3)      DEFAULT 0                    NOT NULL,
    "CREATED"     TIMESTAMP      DEFAULT TIMESTAMP '1000-01-01 00:00:00' NOT NULL,
    "CREATED_BY"  NUMBER(10)     DEFAULT 0                    NOT NULL,
    "MODIFIED"    TIMESTAMP      DEFAULT TIMESTAMP '1000-01-01 00:00:00' NOT NULL,
    "MODIFIED_BY" NUMBER(10)     DEFAULT 0                    NOT NULL,
    "LANGUAGE"    CHAR(7)        DEFAULT ' '                  NOT NULL,
    "PARAMS"      CLOB
);

CREATE UNIQUE INDEX "IDX_CATEGORIES_ALIAS"
    ON "WW_CATEGORIES" ("ALIAS");

ALTER TABLE "WW_CATEGORIES"
    ADD CONSTRAINT "IDX_CATEGORIES_PARENT_ID_LEVEL"
    UNIQUE ("PARENT_ID", "LEVEL");

CREATE INDEX "IDX_CATEGORIES_CREATED_BY"
    ON "WW_CATEGORIES" ("CREATED_BY");

CREATE INDEX "IDX_CATEGORIES_LANGUAGE"
    ON "WW_CATEGORIES" ("LANGUAGE");

CREATE INDEX "IDX_CATEGORIES_LFT_RGT"
    ON "WW_CATEGORIES" ("LFT", "RGT");

CREATE INDEX "IDX_CATEGORIES_PATH"
    ON "WW_CATEGORIES" ("PATH");

CREATE TABLE "WW_ARTICLES"
(
    "ID"          NUMBER(10) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "CATEGORY_ID" NUMBER(10)     DEFAULT 0,
    "PAGE_ID"     NUMBER(10)     DEFAULT 0                    NOT NULL,
    "TYPE"        CHAR(15)       DEFAULT 'bar'                NOT NULL,
    "PRICE"       NUMBER(20, 6)  DEFAULT 0.0,
    "TITLE"       VARCHAR2(255)  DEFAULT ' '                  NOT NULL,
    "ALIAS"       VARCHAR2(255)  DEFAULT ' '                  NOT NULL,
    "INTROTEXT"   CLOB,
    "STATE"       NUMBER(3)      DEFAULT 0                    NOT NULL,
    "ORDERING"    NUMBER(10)     DEFAULT 0                    NOT NULL,
    "CREATED"     TIMESTAMP      DEFAULT TIMESTAMP '1000-01-01 00:00:00' NOT NULL,
    "CREATED_BY"  NUMBER(10)     DEFAULT 0                    NOT NULL,
    "LANGUAGE"    CHAR(7)        DEFAULT ' '                  NOT NULL,
    "PARAMS"      CLOB
);

ALTER TABLE "WW_ARTICLES"
    ADD CONSTRAINT "PK_WW_ARTICLES"
        PRIMARY KEY ("ID");

ALTER TABLE "WW_ARTICLES"
    ADD CONSTRAINT "FK_ARTICLES_CATEGORY_ID"
        FOREIGN KEY ("CATEGORY_ID") REFERENCES "WW_CATEGORIES" ("ID") ON DELETE SET NULL;

ALTER TABLE "WW_ARTICLES"
    ADD CONSTRAINT "FK_ARTICLES_CATEGORY_MORE"
        FOREIGN KEY ("PAGE_ID", "CREATED_BY") REFERENCES "WW_CATEGORIES" ("PARENT_ID", "LEVEL");

CREATE UNIQUE INDEX "IDX_ARTICLES_ALIAS"
    ON "WW_ARTICLES" ("TYPE", "ALIAS");

CREATE INDEX "IDX_ARTICLES_CATEGORY_ID"
    ON "WW_ARTICLES" ("CATEGORY_ID");

CREATE INDEX "IDX_ARTICLES_CREATED_BY"
    ON "WW_ARTICLES" ("CREATED_BY");

CREATE INDEX "IDX_ARTICLES_LANGUAGE"
    ON "WW_ARTICLES" ("LANGUAGE");

CREATE INDEX "IDX_ARTICLES_PAGE_ID"
    ON "WW_ARTICLES" ("PAGE_ID");

CREATE VIEW "WW_ARTICLES_VIEW" AS SELECT * FROM "WW_ARTICLES";
